"""Private file store (FR-014, THR-12): a local folder outside any served path.

Files are stored under random UUID names and served only through API-12.
"""

import uuid
from pathlib import Path

from app.config import get_settings


def _root() -> Path:
    root = Path(get_settings().storage_dir)
    root.mkdir(parents=True, exist_ok=True)
    return root


def save(data: bytes) -> str:
    key = uuid.uuid4().hex
    (_root() / key).write_bytes(data)
    return key


def path_for(key: str) -> Path:
    # Keys are generated by save(); reject anything else so a stored key can't escape the folder.
    if not key or not all(c in "0123456789abcdef" for c in key):
        raise ValueError("invalid storage key")
    return _root() / key


def read(key: str) -> bytes:
    return path_for(key).read_bytes()
